"""Interactive paired feature-ablation report, without external dependencies."""
import json
from pathlib import Path
OUT=Path(__file__).resolve().parents[1]/'results/transfermarkt_models'

def render(metrics,bank,curves,differences):
    data=json.dumps(dict(metrics=metrics,bank=bank,curves=curves,differences=differences))
    page='''<!doctype html><meta charset="utf-8"><title>Transfermarkt model comparison</title>
<style>body{font:15px system-ui;max-width:1300px;margin:25px auto;padding:20px;color:#172c38;background:#f5f8fa}h1{font-size:28px}section{background:white;border:1px solid #dce4e8;border-radius:10px;padding:20px;margin:20px 0}select{padding:10px;margin:5px;border:1px solid #a8b7c0;border-radius:5px}table{border-collapse:collapse;width:100%;font-size:13px}td,th{padding:9px;text-align:right;border-bottom:1px solid #ddd}td:first-child,th:first-child{text-align:left}.scroll{overflow:auto}svg{width:100%;max-height:420px}.note{color:#52636c;line-height:1.5}</style>
<h1>Do historical Transfermarkt values improve the models?</h1>
<p>Paired refits on the same <b>19,263 train</b> and <b>1,447 test</b> rows. FIFA ratings, form, odds and team identity remain in the models.</p>
<p class="note">Added features: home and away log starting-XI market values, plus missing-value indicators. Values strictly predate the match; missing values use medians fitted only on each training fold. Complete valuation coverage: <b>12,476 / 19,263 train (64.8%)</b> and <b>1,432 / 1,447 test (99.0%)</b>. No model, feature or betting-rule tuning on test. Test season: 2022/23, previously examined.</p>
<section><h2>Prediction quality</h2><p>Log loss and Brier: lower is better. AUC: higher is better. Negative change favors adding values. The intervals use paired calendar-week resampling.</p><label>Evaluation <select id="quality"><option>Test</option><option>Train chronological OOF</option><option>Train in-sample</option></select></label><div class="scroll" id="quality-table"></div></section>
<section><h2>Profit and maximum drawdown by league</h2><div id="controls"></div><p class="note">Each league starts with $1,000 separately. All leagues is a separate pooled $1,000 simulation, not the sum of the league rows. Flat $1, quarter Kelly and robust quarter Kelly use the existing rules: 2% match cap, 10% daily cap; robust Kelly subtracts 2 percentage points from probability. Bet365 historical odds, no fees. Drawdown uses daily closing bankrolls.</p><div class="scroll" id="profit-table"></div><h3>Cumulative net profit</h3><svg id="chart" viewBox="0 0 1050 390" role="img" aria-label="Cumulative profits comparing baseline with Transfermarkt values"></svg><div id="legend"></div></section>
<section><h2>How to interpret this</h2><p>Train in-sample profits measure fit and can be optimistic. Chronological OOF covers the 2020/21 and 2021/22 seasons, each predicted from strictly earlier matches. Models are finally refitted on all training rows before predicting test. No calibration or recency selection is changed in this isolated feature experiment.</p><p>The market-value archive lacks early starting lineups, so many older training rows have missing values. The original duplicate test fixture is retained equally in both variants to preserve your existing sample. Historical actual starters imply predictions near kickoff. Archive valuation dates are not independently verified publication timestamps. A test profit increase alone does not establish an improvement.</p><p>Model files, feature coverage, fold audit, predictions, metrics and bankroll tables are saved in <code>results/transfermarkt_models</code>.</p></section>
<script>const data=__DATA__;
const fmt=(x,n=3)=>Number(x).toLocaleString(undefined,{minimumFractionDigits:n,maximumFractionDigits:n});
const money=x=>'$'+fmt(x,2);const pct=x=>fmt(x*100,2)+'%';
function table(headers,rows){return '<table><thead><tr>'+headers.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(x=>'<td>'+x+'</td>').join('')+'</tr>').join('')+'</tbody></table>'}
function quality(){const split=document.querySelector('#quality').value;let rows=[];for(const model of new Set(data.metrics.map(r=>r.model))){const a=data.metrics.find(r=>r.split===split&&r.league==='All'&&r.model===model&&r.variant==='Baseline'),b=data.metrics.find(r=>r.split===split&&r.league==='All'&&r.model===model&&r.variant==='With values');if(!a||!b)continue;const d=data.differences.find(r=>r.split===split&&r.model===model);rows.push([model,fmt(a.log_loss,5),fmt(b.log_loss,5),fmt(b.log_loss-a.log_loss,5),d?fmt(d.ci_low,5)+' to '+fmt(d.ci_high,5):'—',fmt(a.auc,4)+' → '+fmt(b.auc,4),fmt(a.brier,4)+' → '+fmt(b.brier,4)])}document.querySelector('#quality-table').innerHTML=table(['Model','Baseline loss','With values loss','Change','95% interval','AUC','Brier'],rows)}document.querySelector('#quality').onchange=quality;
const choices={};for(const field of ['split','model','league','method']){let label=document.createElement('label');label.textContent=field+' ';let s=document.createElement('select');s.setAttribute('aria-label',field);for(const v of new Set(data.curves.map(r=>r[field])))s.add(new Option(v,v));if(field==='split')s.value='Test';if(field==='method')s.value='Robust quarter Kelly';s.onchange=draw;choices[field]=s;label.append(s);document.querySelector('#controls').append(label)}
function draw(){const get=r=>['split','model','method'].every(k=>r[k]===choices[k].value);let selected=data.bank.filter(get);let rows=[];for(const league of ['All','E0','SP1','D1','I1']){let a=selected.find(r=>r.league===league&&r.variant==='Baseline'),b=selected.find(r=>r.league===league&&r.variant==='With values');if(a&&b)rows.push([league,a.matches,money(a.net),money(b.net),money(b.net-a.net),pct(a.max_drawdown),pct(b.max_drawdown),a.bets+' / '+b.bets])}document.querySelector('#profit-table').innerHTML=table(['League','Matches','Baseline profit','With values profit','Profit change','Baseline max DD','With values max DD','Bets base / values'],rows);
let lines=data.curves.filter(r=>get(r)&&r.league===choices.league.value);let dates=[...new Set(lines.flatMap(r=>r.points.map(p=>p.date)).filter(d=>d!=='Start'))].sort();let vals=lines.flatMap(r=>r.points.map(p=>p.net));let lo=Math.min(0,...vals),hi=Math.max(0,...vals);if(hi===lo)hi=lo+1;const y=v=>330-(v-lo)/(hi-lo)*290,x=d=>d==='Start'?90:90+(dates.indexOf(d)+1)/Math.max(1,dates.length)*900;let svg='';for(let i=0;i<5;i++){let v=lo+(hi-lo)*i/4;svg+=`<line x1="90" x2="990" y1="${y(v)}" y2="${y(v)}" stroke="#ddd"/><text x="0" y="${y(v)}">$${v.toFixed(0)}</text>`}let colors=['#9c6b29','#007a89'];lines.forEach((r,i)=>svg+=`<polyline fill="none" stroke="${colors[i]}" stroke-width="2.5" points="${r.points.map(p=>`${x(p.date)},${y(p.net)}`).join(' ')}"/>`);svg+=`<text x="90" y="365">${dates[0]||''}</text><text x="890" y="365">${dates.at(-1)||''}</text>`;document.querySelector('#chart').innerHTML=svg;document.querySelector('#legend').innerHTML=lines.map((r,i)=>`<span style="color:${colors[i]}">${r.variant}: ${money(r.points.at(-1).net)}</span>`).join(' | ')}quality();draw();</script>'''
    (OUT/'report.html').write_text(page.replace('__DATA__',data),encoding='utf-8')
    policy_path=OUT/'selection_strategy_policy.json'
    if policy_path.exists():
        from report_transfermarkt_strategies import install
        policy=json.loads(policy_path.read_text())
        install(list(dict.fromkeys(r['model'] for r in metrics)),policy['strategies'],policy['sizing'])
